/* megaform sets font-family on label/input/select/textarea with !important, so an authored
   <span> inside a <label> inherits the HOST typeface no matter what the shell root declares.
   Element selectors are (0,3,1) here - above megaform, below every authored class rule - and
   <i> is left alone so Font Awesome keeps its own family. */
.mfp.mfp-pdo.mfp-native-generated label,.mfp.mfp-pdo.mfp-native-generated span,.mfp.mfp-pdo.mfp-native-generated p,.mfp.mfp-pdo.mfp-native-generated div,.mfp.mfp-pdo.mfp-native-generated ul,.mfp.mfp-pdo.mfp-native-generated li,.mfp.mfp-pdo.mfp-native-generated h1,.mfp.mfp-pdo.mfp-native-generated h2,.mfp.mfp-pdo.mfp-native-generated h3,.mfp.mfp-pdo.mfp-native-generated button{font-family:inherit!important}
.mfp.mfp-pdo.mfp-native-generated .mf-field-label{display:none!important}
/* A wizard's page-break Section renders a visible heading the mock has no room for - it exists to
   split the pages, not to be seen. */
.mfp.mfp-pdo.mfp-native-generated .mf-section-break,.mfp.mfp-pdo.mfp-native-generated .mf-section-title{display:none!important}
.mfp.mfp-pdo.mfp-native-generated .mf-field-group{margin:0!important;width:100%}
.mfp.mfp-pdo.mfp-native-generated .mf-form-title,.mfp.mfp-pdo.mfp-native-generated .mf-form-description,.mfp.mfp-pdo.mfp-native-generated .mf-form-actions{display:none!important}
.mfp.mfp-pdo.mfp-native-generated .mf-option-item{margin:0!important}
